class Provider {
  + name : string
  + location : string
}

class Cruise {
  + number : int
  + name : string
  + startDate : date
  + endDate : date
}

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Guest {
  + name : string
  + isVIP : boolean
}

class Ship {
  + name : string
  + deckCount : int
  + length : float
  + passengerCount : int
}

class TravelAgency {
  + name : string
  + address : string
}

class Booking {
  + bookingNumber : int
  + bookingDate : date
}

class DestinationArea {
  + name : string
  + seaName : string
}

class Show {
  + title : string
  + duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise
Cruise "*" -- "*" Employee
