Cruise "1" -- "*" Show
Cruise "1" -- "*" Ticket
Cruise "*" -- "*" Guest
TravelAgency "1" -- "*" Booking
Booking "*" -- "1" Cruise
Guest "1" -- "*" Ticket
Ticket "*" -- "1" Cruise

@enduml

